65	/****************************************************************************
66	 * Private Types
67	 ****************************************************************************/
68	
69	/* EPHY register-value pair for initialization sequences */
70	
71	struct ephy_regval_s
72	{
73	  uint8_t offset;
74	  uint16_t value;
