260	/****************************************************************************
261	 * Private Functions — EPHY Initialization
262	 *
263	 * CV181x has a built-in EPHY that must be initialized before the GMAC
264	 * can communicate with it via MDIO.
265	 * Reference: Manual §2.8, §10.3 Phase 1.2
266	 ****************************************************************************/
267	
268	static void ephy_write_seq(uintptr_t base, const struct ephy_regval_s *seq,
269	                           unsigned int count)
270	{
271	  unsigned int i;
272	
273	  for (i = 0; i < count; i++)
274	    {
275	      putreg32(seq[i].value, base + seq[i].offset);
276	    }
277	}
278	
279	static void ephy_led_pinmux(void)
280	{
281	  /* Match the CV181x U-Boot board-level EPHY LED/selphy setup.
282	   * Registers at 0x030010e0, 0x030010e4, 0x050270b0, 0x050270b4.
283	   */
284	
285	  putreg32(0x05, 0x030010e0);
286	  putreg32(0x05, 0x030010e4);
287	  putreg32(0x11111111, 0x050270b0);
288	  putreg32(0x11111111, 0x050270b4);
289	}
290	
291	static void ephy_full_analog_init(uintptr_t phy_base, uintptr_t phy_top)
292	{
293	  static const struct ephy_regval_s page16_100baset[] =
294	  {
295	    {0x68, 0x1000}, {0x6c, 0x3020}, {0x70, 0x5040}, {0x74, 0x7060},
296	    {0x58, 0x1708}, {0x5c, 0x3827}, {0x60, 0x5748}, {0x64, 0x7867},
297	  };
298	
299	  static const struct ephy_regval_s page17_100baset[] =
300	  {
301	    {0x40, 0x9080}, {0x44, 0xb0a0}, {0x48, 0xd0c0}, {0x4c, 0xf0e0},
302	    {0x50, 0x9788}, {0x54, 0xb8a7}, {0x58, 0xd7c8}, {0x5c, 0xf8e7},
303	  };
304	
305	  static const struct ephy_regval_s page10_link_pulse[] =
306	  {
307	    {0x40, 0x3e00}, {0x44, 0x7864}, {0x48, 0x6470}, {0x4c, 0x5f62},
308	    {0x50, 0x5a5a}, {0x54, 0x5458}, {0x58, 0xb23a}, {0x5c, 0x94a0},
309	    {0x60, 0x9092}, {0x64, 0x8a8e}, {0x68, 0x8688}, {0x6c, 0x8484},
310	    {0x70, 0x0082},
311	  };
312	
313	  static const struct ephy_regval_s page11_tp_idle[] =
314	  {
315	    {0x40, 0x5252}, {0x44, 0x5252}, {0x48, 0x4b52}, {0x4c, 0x3d47},
316	    {0x50, 0xaa99}, {0x54, 0x989e}, {0x58, 0x9395}, {0x5c, 0x9091},
317	    {0x60, 0x8e8f}, {0x64, 0x8d8e}, {0x68, 0x8c8c}, {0x6c, 0x8b8b},
318	    {0x70, 0x008a},
319	  };
320	
321	  static const struct ephy_regval_s page13_10baset[] =
322	  {
323	    {0x40, 0x1e0a}, {0x44, 0x3862}, {0x48, 0x1e62}, {0x4c, 0x2a08},
324	    {0x50, 0x244c}, {0x54, 0x1a44}, {0x58, 0x061c},
325	  };
326	
327	  static const struct ephy_regval_s page14_10baset[] =
328	  {
329	    {0x40, 0x2d30}, {0x44, 0x3470}, {0x48, 0x0648}, {0x4c, 0x261c},
330	    {0x50, 0x3160}, {0x54, 0x2d5e},
331	  };
332	
333	  static const struct ephy_regval_s page15_10baset[] =
334	  {
335	    {0x40, 0x2922}, {0x44, 0x366e}, {0x48, 0x0752}, {0x4c, 0x2556},
336	    {0x50, 0x2348}, {0x54, 0x0c30},
337	  };
338	
339	  static const struct ephy_regval_s page16_10baset[] =
340	  {
341	    {0x40, 0x1e08}, {0x44, 0x3868}, {0x48, 0x1462}, {0x4c, 0x1a0e},
342	    {0x50, 0x305e}, {0x54, 0x2f62},
343	  };
344	
345	  static const struct ephy_regval_s page18_cv181x[] =
346	  {
347	    {0x48, 0x0808}, {0x4c, 0x0808}, {0x50, 0x32f8}, {0x54, 0xf8dc},
348	  };
349	
350	  /* Switch to page 0 */
351	  putreg32(0x0001, phy_top + 0x04);
352	  putreg32(0x0000, phy_base + 0x7c);
353	
354	  /* Page 5: Base configuration */
355	  putreg32(0x0500, phy_base + 0x7c);
356	  putreg32(0x5a5a, phy_base + 0x64);
357	  putreg32(0x0000, phy_base + 0x54);
358	  putreg32(0x0bb0, phy_base + 0x58);
359	  putreg32(0x0c10, phy_base + 0x5c);
360	  putreg32(0x0003, phy_base + 0x68);
361	  putreg32(0x0000, phy_base + 0x54);
362	
363	  /* Page 16: 100BASE-T configuration */
364	  putreg32(0x1000, phy_base + 0x7c);
365	  ephy_write_seq(phy_base, page16_100baset,
366	                 sizeof(page16_100baset) / sizeof(page16_100baset[0]));
367	
368	  /* Page 17: more 100BASE-T */
369	  putreg32(0x1100, phy_base + 0x7c);
370	  ephy_write_seq(phy_base, page17_100baset,
371	                 sizeof(page17_100baset) / sizeof(page17_100baset[0]));
372	
373	  /* Page 5: calibration */
374	  putreg32(0x0500, phy_base + 0x7c);
375	  putreg32(getreg32(phy_base + 0x40) | 0x0001, phy_base + 0x40);
376	  putreg32(getreg32(phy_base + 0x4c) | 0x0820, phy_base + 0x4c);
377	
378	  /* Page 10: link pulse */
379	  putreg32(0x0a00, phy_base + 0x7c);
380	  ephy_write_seq(phy_base, page10_link_pulse,
381	                 sizeof(page10_link_pulse) / sizeof(page10_link_pulse[0]));
382	
383	  /* Page 11: TP idle */
384	  putreg32(0x0b00, phy_base + 0x7c);
385	  ephy_write_seq(phy_base, page11_tp_idle,
386	                 sizeof(page11_tp_idle) / sizeof(page11_tp_idle[0]));
387	
388	  /* Page 13-16: 10BASE-T */
389	  putreg32(0x0d00, phy_base + 0x7c);
390	  ephy_write_seq(phy_base, page13_10baset,
391	                 sizeof(page13_10baset) / sizeof(page13_10baset[0]));
392	
393	  putreg32(0x0e00, phy_base + 0x7c);
394	  ephy_write_seq(phy_base, page14_10baset,
395	                 sizeof(page14_10baset) / sizeof(page14_10baset[0]));
396	
397	  putreg32(0x0f00, phy_base + 0x7c);
398	  ephy_write_seq(phy_base, page15_10baset,
399	                 sizeof(page15_10baset) / sizeof(page15_10baset[0]));
400	
401	  putreg32(0x1000, phy_base + 0x7c);
402	  ephy_write_seq(phy_base, page16_10baset,
403	                 sizeof(page16_10baset) / sizeof(page16_10baset[0]));
404	
405	  /* Page 1: additional tuning */
406	  putreg32(0x0100, phy_base + 0x7c);
407	  putreg32(getreg32(phy_base + 0x68) & ~0x0f00, phy_base + 0x68);
408	
409	  /* Page 19: misc */
410	  putreg32(0x1300, phy_base + 0x7c);
411	  putreg32(0x0012, phy_base + 0x58);
412	  putreg32(0x6848, phy_base + 0x5c);
413	
414	  /* Page 18: CV181x specific */
415	  putreg32(0x1200, phy_base + 0x7c);
416	  ephy_write_seq(phy_base, page18_cv181x,
417	                 sizeof(page18_cv181x) / sizeof(page18_cv181x[0]));
418	
419	  /* Return to page 0, start auto-negotiation */
420	  putreg32(0x0000, phy_base + 0x7c);
421	  putreg32(0x090e, phy_top);
422	  putreg32(getreg32(phy_base) | 0x0100, phy_base);
423	}
