1033	/****************************************************************************
1034	 * Name: gmac_set_speed_duplex
1035	 *
1036	 * Description:
1037	 *   Configure GMAC speed and duplex mode based on PHY negotiation result.
1038	 *
1039	 * Reference: Manual §10.9
1040	 ****************************************************************************/
1041	
1042	static void gmac_set_speed_duplex(uintptr_t gmac_base, int speed, int duplex)
1043	{
1044	  uint32_t val;
1045	
1046	  val = getreg32(gmac_base + GMAC_CONTROL);
1047	
1048	  /* Clear speed and duplex bits */
1049	
1050	  val &= ~(GMAC_CONTROL_FES | GMAC_CONTROL_DM);
1051	
1052	  /* Set speed: FES=1 for 100Mbps, FES=0 for 10Mbps */
1053	
1054	  if (speed == 100)
1055	    {
1056	      val |= GMAC_CONTROL_FES;
1057	    }
1058	
1059	  /* Set duplex: DM=1 for full duplex */
1060	
1061	  if (duplex)
1062	    {
1063	      val |= GMAC_CONTROL_DM;
1064	    }
1065	
1066	  putreg32(val, gmac_base + GMAC_CONTROL);
1067	}
