 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/drivers/drivers.h>
#include <nuttx/fs/fs.h>
#include <nuttx/kmalloc.h>
#include <nuttx/memoryregion.h>
#include <sys/param.h>
#include <sys/mman.h>

/****************************************************************************
 * Private Data
 ****************************************************************************/

#ifdef CONFIG_BOARD_MEMORY_RANGE
static const struct memory_region_s g_memory_region[] =
  {
    CONFIG_BOARD_MEMORY_RANGE
  };
#else
extern uint8_t _stext[];           /* Start of .text */
extern uint8_t _etext[];           /* End_1 of .text + .rodata */
extern uint8_t _sdata[];           /* Start of .data */
extern uint8_t _edata[];           /* End+1 of .data */
extern uint8_t _sbss[];            /* Start of .bss */
extern uint8_t _ebss[];            /* End+1 of .bss */

static const struct memory_region_s g_memory_region[] =
  {
    { (uintptr_t)_stext, (uintptr_t)_etext, PROT_EXEC | PROT_READ },
    { (uintptr_t)_sdata, (uintptr_t)_edata, PROT_WRITE | PROT_READ },
    { (uintptr_t)_sbss,  (uintptr_t)_ebss,  PROT_WRITE | PROT_READ },
    { 0, 0, 0 },
  };
#endif

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

/* Character driver methods */

static ssize_t devmem_read(FAR struct file *filep, FAR char *buffer,
                           size_t buflen);
static ssize_t devmem_write(FAR struct file *filep, FAR const char *buffer,
                            size_t buflen);
static off_t   devmem_seek(FAR struct file *filep, off_t offset, int whence);
static int     devmem_mmap(FAR struct file *filep,
                           FAR struct mm_map_entry_s *map);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct file_operations g_devmem_fops =
{
  NULL,                  /* open */
  NULL,                  /* close */
  devmem_read,           /* read */
  devmem_write,          /* write */
  devmem_seek,           /* seek */
  NULL,                  /* ioctl */
  devmem_mmap,           /* mmap */
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: devmem_read
 ****************************************************************************/

static ssize_t devmem_read(FAR struct file *filep, FAR char *buffer,
                           size_t buflen)
{
  FAR struct memory_region_s *region = filep->f_inode->i_private;
  uintptr_t start;
  uintptr_t end;
  ssize_t len;
  int i;

  for (i = 0; region[i].start != 0 && region[i].end != 0; i++)
    {
      start = region[i].start + filep->f_pos;
      end = MIN(start + buflen, region[i].end);
      len = end - start;
      if (len > 0 && (region[i].flags & PROT_READ))
        {
          memcpy(buffer, (FAR const void *)start, len);
          filep->f_pos += len;
          return len;
        }
    }

  return -EINVAL;
}

/****************************************************************************
 * Name: devmem_write
 ****************************************************************************/

static ssize_t devmem_write(FAR struct file *filep, FAR const char *buffer,
                            size_t buflen)
{
  FAR struct memory_region_s *region = filep->f_inode->i_private;
  uintptr_t start;
  uintptr_t end;
  ssize_t len;
  int i;

  for (i = 0; region[i].start != 0 && region[i].end != 0; i++)
    {
      start = region[i].start + filep->f_pos;
      end = MIN(start + buflen, region[i].end);
      len = end - start;
      if (len > 0 && (region[i].flags & PROT_WRITE))
        {
          memcpy((FAR void *)start, buffer, len);
          filep->f_pos += len;
          return len;
        }
    }

  return -EINVAL;
}

/****************************************************************************
 * Name: devmem_seek
 ****************************************************************************/

static off_t devmem_seek(FAR struct file *filep, off_t offset, int whence)
{
  FAR struct memory_region_s *region = filep->f_inode->i_private;
  int i;

  switch (whence)
    {
      case SEEK_CUR:
        offset += filep->f_pos;
        break;

      case SEEK_SET:
        break;

      case SEEK_END:
        for (i = 0; region[i].start != 0 && region[i].end != 0; i++)
          {
            offset += region[i].end - region[i].start;
          }

        break;

      default:
        return -EINVAL;
    }

  if (offset < 0)
    {
      return -EINVAL;
    }

  filep->f_pos = offset;
  return filep->f_pos;
}

/****************************************************************************
 * Name: devmem_mmap
 ****************************************************************************/

static int devmem_mmap(FAR struct file *filep,
                       FAR struct mm_map_entry_s *map)
{
  FAR struct memory_region_s *region = filep->f_inode->i_private;
  uintptr_t start;
  uintptr_t end;
  int i;

  if (map->offset < 0)
    {
      return -EINVAL;
    }

  start = map->offset;
  end = start + map->length;

  for (i = 0; region[i].start != 0 && region[i].end != 0; i++)
    {
      if (start >= region[i].start && end <= region[i].end)
        {
          map->vaddr = (FAR void *)start;
          return 0;
        }
    }

  return -EINVAL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: devmem_register
 *
 * Description:
 *   Create an MEM driver.
 *
 * Returned Value:
 *   Zero (OK) on success; A negated errno value on failure.
 *
 ****************************************************************************/

int devmem_register(void)
{
  return devmem_register_region("/dev/mem", g_memory_region);
}

/****************************************************************************
 * Name: devmem_register_region
 *
 * Description:
 *   Create an MEM driver with customize region.
 *
 * Returned Value:
 *   Zero (OK) on success; A negated errno value on failure.
 *
 ****************************************************************************/

int devmem_register_region(FAR const char *path,
                           FAR const struct memory_region_s *region)
{
  if (path == NULL || region == NULL)
    {
      return -EINVAL;
    }

  return register_driver(path, &g_devmem_fops, 0666, (FAR void *)region);
}

content.text:
NuttX 有 `/dev/mem` 设备驱动（[dev_mem.c](nuttx/drivers/misc/dev_mem.c)），但 NSH **没有内置的 `devmem` 命令**。有几种替代方式：

### 方法一：直接用 NSH 的 `dd` 命令读写 `/dev/mem`

前提是内核启用了 `CONFIG_DEV_MEM`，并且 board 通过 `devmem_register_region()` 注册了允许访问的内存区域。然后：

```bash
# 读取某个地址（通过 seek 定位）
nsh> dd if=/dev/mem of=/dev/console bs=4 count=1 skip=<offset>

# 写入
nsh> echo -ne '\xXX\xXX\xXX\xXX' > /dev/mem
```

但这种方式对地址计算很不方便。

### 方法二：使用 NSH 的 `md`（memory display）和 `mw`（memory write）命令

NuttX NSH 内置了更实用的内存调试命令：

```
nsh> md 0x03000000 4       # 从地址 0x03000000 读取 4 个 32-bit word
nsh> mw 0x03000000 0x12345678  # 向地址写入一个 32-bit 值
```

- `md` — memory display，支持按 byte/halfword/word 显示
- `mw` — memory write

### 方法三：编写一个简单的 NSH 应用

如果 NSH 没有 `md`/`mw`，可以自己写一个最小的 devmem 工具：

```c
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>

int main(int argc, char *argv[])
{
  if (argc < 2)
    {
      fprintf(stderr, "Usage: devmem <address> [width] [value]\n");
      return 1;
    }

  uintptr_t addr = strtoul(argv[1], NULL, 0);
  int width = (argc > 2) ? atoi(argv[2]) : 32;

  int fd = open("/dev/mem", O_RDWR | O_SYNC);
  if (fd < 0)
    {
      perror("open /dev/mem");
      return 1;
    }

  uintptr_t page = addr & ~(4096 - 1);
  size_t len = 4096;
  void *map = mmap(NULL, len, PROT_READ | PROT_WRITE, MAP_SHARED, fd, page);
  if (map == MAP_FAILED)
    {
      perror("mmap");
      close(fd);
      return 1;
    }

  volatile void *ptr = (char *)map + (addr & (4096 - 1));

  if (argc > 3)
    {
      /* 写 */
      uint32_t val = strtoul(argv[3], NULL, 0);
      *(volatile uint32_t *)ptr = val;
    }

  /* 读 */
  printf("0x%08x: 0x%08x\n", addr, *(volatile uint32_t *)ptr);

  munmap(map, len);
  close(fd);
  return 0;
}
```

### 总结

| 方式 | 是否可用 | 说明 |
|---|---|---|
| `devmem` 命令 | ❌ NSH 无内置 | 需自己编写或移植 |
| `md` / `mw` | ✅ NSH 内置 | 最常用，直接读写物理地址 |
| `dd` + `/dev/mem` | ✅ 需 `CONFIG_DEV_MEM` | 不方便，需要手动算 offset |
| 自写应用 + `mmap` | ✅ 需 `CONFIG_DEV_MEM` | 灵活但需要代码 |

**实际调试中推荐用 `md`/`mw`**，这是 NuttX 嵌入式调试最常用的方式。

