/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <errno.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define WIDTH_8   8
#define WIDTH_16  16
#define WIDTH_32  32

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void show_usage(void)
{
  fprintf(stderr,
    "Usage: devmem <address> [width] [value]\n"
    "\n"
    "  address  Physical address to access (hex with 0x prefix, or decimal)\n"
    "  width    Access width: 8, 16, 32 (default: 32)\n"
    "  value    Value to write (if omitted, read operation)\n"
    "\n"
    "Examples:\n"
    "  devmem 0x04010000           Read 32-bit from GMAC DMA status\n"
    "  devmem 0x04010000 16        Read 16-bit\n"
    "  devmem 0x04010000 32 0x1    Write 32-bit value\n");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * devmem_main
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  uintptr_t addr;
  uint32_t  width = WIDTH_32;
  uint32_t  value;
  bool      do_write = false;
  FAR char *endptr;

  if (argc < 2)
    {
      show_usage();
      return EXIT_FAILURE;
    }

  /* Parse address */

  addr = strtoul(argv[1], &endptr, 0);
  if (*endptr != '\0' || endptr == argv[1])
    {
      fprintf(stderr, "devmem: invalid address '%s'\n", argv[1]);
      return EXIT_FAILURE;
    }

  /* Parse optional width */

  if (argc > 2)
    {
      width = strtoul(argv[2], &endptr, 0);
      if (*endptr != '\0')
        {
          fprintf(stderr, "devmem: invalid width '%s'\n", argv[2]);
          return EXIT_FAILURE;
        }

      if (width != WIDTH_8 && width != WIDTH_16 && width != WIDTH_32)
        {
          fprintf(stderr, "devmem: width must be 8, 16, or 32\n");
          return EXIT_FAILURE;
        }
    }

  /* Parse optional value (write mode) */

  if (argc > 3)
    {
      value = strtoul(argv[3], &endptr, 0);
      if (*endptr != '\0')
        {
          fprintf(stderr, "devmem: invalid value '%s'\n", argv[3]);
          return EXIT_FAILURE;
        }

      do_write = true;
    }

  /* Access the address */

  switch (width)
    {
      case WIDTH_8:
        {
          volatile uint8_t *ptr = (volatile uint8_t *)addr;
          if (do_write)
            {
              *ptr = (uint8_t)value;
              printf("W 0x%08" PRIxPTR " = 0x%02" PRIx8 "\n",
                     addr, (uint8_t)value);
            }
          else
            {
              printf("0x%08" PRIxPTR ": 0x%02" PRIx8 "\n", addr, *ptr);
            }
        }
        break;

      case WIDTH_16:
        {
          volatile uint16_t *ptr = (volatile uint16_t *)addr;
          if (do_write)
            {
              *ptr = (uint16_t)value;
              printf("W 0x%08" PRIxPTR " = 0x%04" PRIx16 "\n",
                     addr, (uint16_t)value);
            }
          else
            {
              printf("0x%08" PRIxPTR ": 0x%04" PRIx16 "\n", addr, *ptr);
            }
        }
        break;

      case WIDTH_32:
      default:
        {
          volatile uint32_t *ptr = (volatile uint32_t *)addr;
          if (do_write)
            {
              *ptr = value;
              printf("W 0x%08" PRIxPTR " = 0x%08" PRIx32 "\n",
                     addr, value);
            }
          else
            {
              printf("0x%08" PRIxPTR ": 0x%08" PRIx32 "\n", addr, *ptr);
            }
        }
        break;
    }

  return EXIT_SUCCESS;
}

