void mmu_ln_map_region(uint32_t ptlevel, uintptr_t lnvaddr, uintptr_t paddr,
                       uintptr_t vaddr, size_t size, uint64_t mmuflags)
{
  uintptr_t end_paddr = paddr + size;
  size_t    page_size = g_pgt_sizes[ptlevel - 1];

  DEBUGASSERT(ptlevel > 0 && ptlevel <= RV_MMU_PT_LEVELS);

  while (paddr < end_paddr)
    {
      mmu_ln_setentry(ptlevel, lnvaddr, paddr, vaddr, mmuflags);
      paddr += page_size;
      vaddr += page_size;
    }
}

size_t mmu_get_region_size(uint32_t ptlevel)
{
  DEBUGASSERT(ptlevel > 0 && ptlevel <= RV_MMU_PT_LEVELS);

  return g_pgt_sizes[ptlevel - 1];
}

 * active, so the page table virtual addresses are actually physical
 * addresses and so forth.
 */

/* Map I/O region, use enough large page tables for the IO region. */

binfo("map I/O regions\n");
mmu_ln_map_region(1, PGT_L1_VBASE, MMU_IO_BASE, MMU_IO_BASE,
                  MMU_IO_SIZE, MMU_THEAD_IO_FLAGS);

/* Map DDR region (kernel code, data, heap, ramdisk live here) */

binfo("map DDR region\n");
mmu_ln_map_region(1, PGT_L1_VBASE, MMU_DDR_BASE, MMU_DDR_BASE,
                  MMU_DDR_SIZE, MMU_KDATA_FLAGS | MMU_THEAD_PMA_FLAGS);

/* PLIC at 0x70000000 is now covered by the expanded I/O L1 mapping above.
 * No separate L2 mapping needed.
 */

/* Map the kernel text and data for L2/L3 */

binfo("map kernel text\n");
map_region(KFLASH_START, KFLASH_START, KFLASH_SIZE,
           MMU_KTEXT_FLAGS | MMU_THEAD_PMA_FLAGS);

binfo("map kernel data\n");
map_region(KSRAM_START, KSRAM_START, KSRAM_SIZE,
           MMU_KDATA_FLAGS | MMU_THEAD_PMA_FLAGS);

